// ============================================================
// M0.9 MODULE: BYTE ↔ UTF-16 POSITION CONVERTER
// ============================================================
// Pure module file - no tests, just function definitions.
// Load from another file:
//   (PathName(thisProcess.nowExecutingPath).pathOnly +/+ "wildcard-visual-m09-module.scd").load;
// ============================================================

// Determine UTF-8 byte length from leading byte
~utf8ByteLength = {|leadingByte|
    var code = leadingByte.ascii;
    case
        { code < 0 } {
            var unsigned = code + 256;
            case
                { unsigned < 194 } { 1 }
                { unsigned < 224 } { 2 }
                { unsigned < 240 } { 3 }
                { unsigned < 248 } { 4 }
                { 1 };
        }
        { code < 128 } { 1 }
        { 1 };
};

// Character count for selectRange length parameter.
// IMPORTANT: Despite the Document.selectRange docs suggesting UTF-16 indexing,
// testing reveals the LENGTH parameter counts CODEPOINTS, not UTF-16 units.
// - Positions: UTF-16 indexed (surrogate pairs = 2 units)
// - Length: Codepoint indexed (each character = 1, regardless of UTF-16 encoding)
// This was discovered via M2 surrogate pair testing: selecting 🎹🎹 (2 chars,
// 4 UTF-16 units) with length=4 incorrectly selected 4 characters (🎹🎹);).
~charCountForSelectRange = {|utf8ByteLen|
    1;  // Every UTF-8 sequence = 1 codepoint = 1 unit for selectRange length
};

// Convert byte position to character position (for use with Document.selectRange)
// Note: Named "byteToUtf16" for historical reasons, but actually returns codepoint position
// which is what selectRange needs for both start position AND length calculations.
~byteToUtf16 = {|text, bytePos|
    var byteIdx = 0, charIdx = 0, textSize = text.size;
    while { byteIdx < bytePos and: { byteIdx < textSize } } {
        var byteLen = ~utf8ByteLength.(text[byteIdx]);
        var charCount = ~charCountForSelectRange.(byteLen);
        byteIdx = byteIdx + byteLen;
        charIdx = charIdx + charCount;
    };
    charIdx;
};

// Convert character position to byte position (for String indexing)
// Note: Named "utf16ToByte" for historical reasons, but takes codepoint position.
~utf16ToByte = {|text, charPos|
    var byteIdx = 0, charIdx = 0, textSize = text.size;
    while { charIdx < charPos and: { byteIdx < textSize } } {
        var byteLen = ~utf8ByteLength.(text[byteIdx]);
        var charCount = ~charCountForSelectRange.(byteLen);
        byteIdx = byteIdx + byteLen;
        charIdx = charIdx + charCount;
    };
    byteIdx;
};

